using GraphApi.Models.USR.Automoviles;namespace GraphApi.Services.USR.Automoviles{    /// <summary>    /// Define las operaciones de negocio y persistencia para Automoviles.    /// </summary>    public interface IAutomovilesService    {        /// <summary>        /// Obtiene la lista de Automoviles con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadAutomoviles>> GetAutomoviles(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Automoviles con filtros opcionales.        /// </summary>        /// <param name="automovilID">Filtro opcional para AutomovilID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="nombreUsuario">Filtro opcional para NombreUsuario.</param>        /// <param name="correoUsuario">Filtro opcional para CorreoUsuario.</param>        /// <param name="marcaID">Filtro opcional para MarcaID.</param>        /// <param name="marca">Filtro opcional para Marca.</param>        /// <param name="modeloID">Filtro opcional para ModeloID.</param>        /// <param name="modelo">Filtro opcional para Modelo.</param>        /// <param name="placas">Filtro opcional para Placas.</param>        /// <param name="color">Filtro opcional para Color.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetAutomovilesDynamic(            int? automovilID,            int? usuarioID,            string? nombreUsuario,            string? correoUsuario,            int? marcaID,            string? marca,            int? modeloID,            string? modelo,            string? placas,            string? color,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Automovile.        /// </summary>        /// <param name="objInput">Datos para crear el Automovile.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadAutomoviles> CreateAutomoviles(            clCreateAutomoviles objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Automovile.        /// </summary>        /// <param name="objInput">Datos para actualizar el Automovile, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadAutomoviles?> UpdateAutomoviles(            clUpdateAutomoviles objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Automovile por su ID.        /// </summary>        /// <param name="nAutomovilesID">ID del Automovile a eliminar.</param>        Task<bool> DeleteAutomoviles(int nAutomovilesID);    }}